from collections import Counter, defaultdict

def transform(grid):
    g=[row[:] for row in grid]; H,W=len(g),len(g[0])
    cnt=Counter(v for row in g for v in row)
    bg=cnt.most_common(1)[0][0]
    pts=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c]!=bg]
    # diagonal lines
    lines=defaultdict(list)
    for r,c,v in pts:
        lines[('m',r-c)].append((r,c,v))
        lines[('a',r+c)].append((r,c,v))
    res=[row[:] for row in g]
    def on_line(kind,k,r,c): return (r-c==k) if kind=='m' else (r+c==k)
    def cells(kind,k):
        out=[]
        for r in range(H):
            c=(r-k) if kind=='m' else (k-r)
            if 0<=c<W: out.append((r,c))
        return out
    # 1-points: fill between same-color partners on shared lines; else full line minus edges
    for r,c,v in pts:
        if v!=1: continue
        for kind,k in [('m',r-c),('a',r+c)]:
            L=lines[(kind,k)]
            if len(L)<2: continue
            partners=[(rr,cc) for rr,cc,vv in L if vv==1 and (rr,cc)!=(r,c)]
            if partners:
                lo=min(min(r,[p[0] for p in partners]), min(p[0] for p in partners))
                top=min(r,min(p[0] for p in partners)); bot=max(r,max(p[0] for p in partners))
                for rr,cc in cells(kind,k):
                    if top<=rr<=bot and res[rr][cc]==bg: res[rr][cc]=1
            else:
                for rr,cc in cells(kind,k):
                    if 0<rr<H-1 and 0<cc<W-1 and res[rr][cc]==bg: res[rr][cc]=1
    # 6-points: on a shared line, draw full perpendicular diagonal
    for r,c,v in pts:
        if v!=6: continue
        for kind,k in [('m',r-c),('a',r+c)]:
            if len(lines[(kind,k)])<2: continue
            pk=('a',r+c) if kind=='m' else ('m',r-c)
            for rr,cc in cells(*pk):
                if res[rr][cc]==bg: res[rr][cc]=6
    return res

